1	var LOG = TemuLogger.createLogger('popup');
2	
3	function send(type, extra) {
4	  return new Promise((res) => chrome.runtime.sendMessage(Object.assign({ type }, extra), res));
5	}
6	function esc(s) {
7	  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
8	}
9	function setMsg(text, cls) {
10	  const el = document.getElementById('msg');
11	  el.textContent = text || '';
12	  el.className = cls || '';
13	}
14	function fmtTs(ts) {
15	  return ts ? new Date(ts).toLocaleString('zh-CN') : '—';
16	}
17	function num(v) { return v != null ? v : '—'; }
18	function editLink(productId) { return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId; }
19	function itemsHtml(items, label, color) {
20	  if (!Array.isArray(items) || !items.length) return '';
21	  return `<div class="items">${esc(label)}${items.map((it) =>
22	    `<a href="${esc(editLink(it.productId))}" target="_blank" style="color:${color}" title="SKC ${esc(it.skc || '-')}">• ${esc((it.name || '商品').slice(0, 22))}</a>`
23	  ).join('')}</div>`;
24	}
25	
26	async function refresh() {
27	  const s = await send('getStatus');
28	  const cfg = (s && s.config) || {};
29	  const stores = (s && s.stores) || {};
30	
31	  document.getElementById('cfg').textContent =
32	    '飞书：' + (cfg.webhook ? (cfg.enabled ? '已启用' : '已停用') : '未配置')
33	    + '　后台：' + (s && s.bgVersion ? s.bgVersion : '旧版·需强制刷新');
34	
35	  const lc = s && s.lastCycle;
36	  const ci = document.getElementById('cycleInfo');
37	  if (lc && lc.ts) {
38	    const failed = /失败|没找到|打不开/.test(lc.summary || '');
39	    ci.textContent = '上次轮巡：' + fmtTs(lc.ts) + (failed ? '（有异常，点轮巡重试）' : '');
40	    ci.className = failed ? 'sub err' : 'sub';
41	  } else {
42	    ci.textContent = '';
43	  }
44	
45	  const names = Object.keys(stores).sort();
46	  const box = document.getElementById('stores');
47	  if (names.length === 0) {
48	    box.innerHTML = '<div class="empty">还没有数据。切到某个店的商品列表页（并点“立即检查”）即可开始监测该店。</div>';
49	    return;
50	  }
51	  box.innerHTML = names.map((name) => {
52	    const L = (stores[name] && stores[name].latest) || {};
53	    return `<div class="store">
54	      <div class="name"><span>🏬 ${esc(name)}</span><span class="r"><span class="t">${fmtTs(L.ts)}</span><span class="del" data-name="${esc(name)}" title="删除该店">✕</span></span></div>
55	      <div class="kv">
56	        <span>在售 <b>${num(L.onSale)}</b></span>
57	        <span>流量待关注 <b>${num(L.trafficWatch)}</b></span>
58	        <span>流量下降 <b style="${typeof L.trafficDecline === 'number' && L.trafficDecline > 0 ? 'color:#d92d20' : ''}">${typeof L.trafficDecline === 'number' ? L.trafficDecline : '—'}</b></span>
59	        <span>总数 ${num(L.total)}</span>
60	        <span>未发布/已下架 ${num(L.unpublished)}/${num(L.removed)}</span>
61	      </div>
62	      ${itemsHtml(L.watchItems, '限流商品：', '#d97706')}
