342	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
343	async function waitForStoreCapture(name, sinceTs, timeout) {
344	  const t0 = Date.now();
345	  while (Date.now() - t0 < (timeout || 25000)) {
346	    const stores = await getStores();
347	    const L = stores[name] && stores[name].latest;
348	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
