361	    if (!tab) { log.warn('Cycle: no goods tab found'); return { ok: false, msg: '没有打开的 Temu 商品页' }; }
362	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
363	    const original = cur && cur.store;
