367	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
368	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
369	    let names;
370	    if (known.length >= 2) {
371	      names = known;
372	      cycleLog.push('店铺(已知)：' + names.join(', '));
373	    } else {
374	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
375	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
376	      cycleLog.push('店铺(探测)：' + names.join(', '));
377	    }
378	    if (names.length === 0) { log.warn('Cycle: no stores identified'); return { ok: false, msg: '没识别到店铺清单' }; }
379	    log.info('Cycle stores: ' + names.length + ' stores: ' + names.join(', '));
380	
381	    for (const name of names) {
382	      if (name === original) continue; // 原店最后再确认；先切别的
383	      const since = Date.now();
384	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
385	      if (!r || !r.ok) { log.warn('Cycle switch FAILED: store=' + name); cycleLog.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
386	      const got = await waitForStoreCapture(name, since, 25000);
387	      cycleLog.push((got ? '✓ ' : '✗ ') + name);
388	      if (got) {
389	        log.info('Cycle captured: store=' + name);
390	      } else {
391	        log.warn('Cycle capture TIMEOUT: store=' + name);
392	      }
393	      // 扫在售清单 → diff 出下架商品（带链接告警）
394	      if (got) {
395	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
396	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount); if (d) { log.warn('Cycle delisted: store=' + name + ' count=' + d); cycleLog.push('  ↳下架' + d + '个'); } }
397	      }
398	    }
