55	async function updateStoreLatest(name, patch) {
56	  const stores = await getStores();
57	  const s = stores[name] || { latest: {}, snapshot: {} };
58	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
59	  stores[name] = s;
60	  await saveStores(stores);
61	  return s;
62	}
63	
64	// ---------------- 飞书 ----------------
65	// template：飞书卡片色条 red/orange/blue/green/turquoise/wathet/purple/violet/carmine/yellow/grey
66	async function sendFeishu(webhook, title, lines, template) {
67	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
68	  const card = {
69	    msg_type: 'interactive',
70	    card: {
71	      header: { title: { tag: 'plain_text', content: title }, template: template || 'red' },
72	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
73	    },
74	  };
75	  try {
76	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
77	    const data = await resp.json().catch(() => ({}));
78	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
79	    if (ok) log.info('Feishu sent OK: ' + title);
80	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
81	  } catch (e) {
82	    log.error('Feishu send FAILED: ' + (e && e.message ? e.message : 'unknown'));
83	    return { ok: false, msg: '发送失败：' + (e && e.message) };
84	  }
85	}
86	
87	// ---------------- 定时必提醒（每天固定时刻强制汇报各店状态） ----------------
88	function parseHHMM(s) {
89	  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
90	  if (!m) return null;
91	  const h = Number(m[1]);
92	  const min = Number(m[2]);
93	  if (h > 23 || min > 59) return null;
94	  return { h, min, label: String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0') };
95	}
96	// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
97	function nextWhen(hhmm) {
98	  const p = parseHHMM(hhmm);
99	  if (!p) return null;
100	  const now = new Date();
101	  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
102	  if (t.getTime() <= now.getTime() + 5000) t.setDate(t.getDate() + 1);
103	  return t.getTime();
104	}
105	function fmtNum(v) { return typeof v === 'number' ? String(v) : '—'; }
106	async function sendMustRemind(slot) {
107	  const cfg = await getConfig();
108	  if (!cfg.enabled || cfg.mustRemindEnabled === false) {
109	    log.info('MustRemind skipped: disabled');
110	    return { ok: false, msg: '未启用' };
111	  }
112	  if (!cfg.webhook) {
113	    log.warn('MustRemind skipped: no webhook');
114	    return { ok: false, msg: '未配置飞书 webhook' };
115	  }
116	  const stores = await getStores();
117	  const names = Object.keys(stores).sort();
118	  const lines = [
119	    '**定时必提醒' + (slot ? ' · ' + slot : '') + '**',
120	    '_插件存活汇报（无异常也会发）_',
121	    '',
122	  ];
123	  if (!names.length) {
124	    lines.push('_暂无店铺数据。请打开 goods/list 或点「轮巡所有店」。_');
125	  } else {
126	    for (const name of names) {
127	      const L = (stores[name] && stores[name].latest) || {};
128	      const stale = L.ts && (Date.now() - L.ts > 2 * 60 * 60 * 1000);
129	      lines.push('**🏬 ' + name + '**' + (stale ? ' ⚠️数据超过2小时未更新' : ''));
130	      lines.push(
131	        '在售 **' + fmtNum(L.onSale) + '**'
132	        + ' · 待关注 **' + fmtNum(L.trafficWatch) + '**'
133	        + ' · 下降 **' + fmtNum(L.trafficDecline) + '**'
134	        + ' · 总数 ' + fmtNum(L.total)
135	      );
136	      lines.push('上次检查：' + (L.ts ? new Date(L.ts).toLocaleString('zh-CN') : '—'));
137	      lines.push('');
138	    }
139	  }
